using Gtk 4.0;

template $AmberolVolumeControl: Widget {
  Button volume_low_button {
    icon-name: "audio-volume-low-symbolic";
    action-name: "volume.toggle-mute";
    valign: center;

    styles [
      "flat",
      "circular",
    ]
  }

  Scale volume_scale {
    hexpand: true;
    margin-end: 6;
  }

  Image volume_high_image {
    icon-name: "audio-volume-high-symbolic";
    margin-end: 10;
  }
}

